import { initTRPC, TRPCError } from "@trpc/server";
import superjson from "superjson";
import { z } from "zod";

/**
 * Initialization of tRPC backend
 * Should be done only once per backend!
 */
const t = initTRPC.create({
  transformer: superjson,
  errorFormatter({ shape }) {
    return shape;
  },
});

/**
 * Export reusable router and procedure helpers
 * that can be used throughout the router
 */
export const createCallerFactory = t.createCallerFactory;
export const createTRPCRouter = t.router;
export const baseProcedure = t.procedure;

export const messageRouter = createTRPCRouter({
  addMessage: baseProcedure
    .input(
      z.object({
        text: z.string().min(1, "Message text cannot be empty"),
      }),
    )
    .mutation(({ input }) => {
      // In a real application this is where you would persist the message
      // to a database, send it to a queue, etc. Here we simply echo it back.
      return {
        success: true,
        message: input.text,
      };
    }),
});

/**
 * The root router used by the server-side caller.
 * If you have multiple sub-routers you can compose them here, e.g.:
 *
 *   export const appRouter = createTRPCRouter({
 *     messages: messageRouter,
 *   });
 */
export const appRouter = createTRPCRouter({
  messages: messageRouter,
});

export type AppRouter = typeof appRouter;

import { appRouter, createCallerFactory } from "./trpc";

/**
 * Create the server-side caller using createCallerFactory.
 *
 * Using the caller directly (instead of HTTP fetch) is the recommended
 * way to invoke tRPC procedures from Next.js Server Actions, Route
 * Handlers, React Server Components, and any other server-only code
 * path because:
 *   - no network round-trip is involved,
 *   - you keep full type-safety,
 *   - you can re-use any context object you would normally inject.
 */
const createCaller = createCallerFactory(appRouter);

/**
 * A request-scoped context. For Server Actions we don't have an HTTP
 * request, so we just provide a minimal placeholder. In a real app you
 * would typically forward headers, cookies, the authenticated user, etc.
 */
const createContext = async () => {
  return {
    // e.g. user, db, headers, etc.
    requestId: crypto.randomUUID(),
  };
};

export const trpcCaller = async () => createCaller(await createContext());

"use server";

import { TRPCClientError } from "@trpc/client";
import { trpcCaller } from "@/server/caller";

export type AddMessageInput = {
  text: string;
};

export type AddMessageResult =
  | { ok: true; success: true; message: string }
  | { ok: false; error: string };

/**
 * Next.js Server Action that calls the tRPC `addMessage` mutation
 * through the server-side caller. Server Actions are async functions
 * that run on the server, so this is the ideal place to invoke tRPC
 * procedures directly without needing an HTTP round-trip.
 */
export async function addMessageAction(
  input: AddMessageInput,
): Promise<AddMessageResult> {
  try {
    const caller = await trpcCaller();
    const result = await caller.messages.addMessage({ text: input.text });

    return {
      ok: true,
      success: result.success,
      message: result.message,
    };
  } catch (error) {
    if (error instanceof TRPCClientError) {
      return {
        ok: false,
        error: error.message,
      };
    }

    return {
      ok: false,
      error:
        error instanceof Error ? error.message : "Unknown server error",
    };
  }
}

"use client";

import { useState, useTransition } from "react";
import { addMessageAction } from "../actions";

type FormState =
  | { status: "idle" }
  | { status: "success"; message: string }
  | { status: "error"; error: string };

export function AddMessageForm() {
  const [text, setText] = useState("");
  const [state, setState] = useState<FormState>({ status: "idle" });
  const [isPending, startTransition] = useTransition();

  async function handleSubmit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();

    if (!text.trim()) {
      setState({ status: "error", error: "Please enter a message." });
      return;
    }

    startTransition(async () => {
      const result = await addMessageAction({ text });
      if (result.ok) {
        setState({
          status: "success",
          message: result.message,
        });
        setText("");
      } else {
        setState({ status: "error", error: result.error });
      }
    });
  }

  return (
    <div className="w-full max-w-md flex flex-col gap-4">
      <form
        onSubmit={handleSubmit}
        className="flex flex-col gap-3 rounded-lg border border-zinc-200 bg-white p-6 shadow-sm dark:border-zinc-800 dark:bg-zinc-900"
      >
        <label
          htmlFor="message"
          className="text-sm font-medium text-zinc-700 dark:text-zinc-200"
        >
          Your message
        </label>
        <input
          id="message"
          name="message"
          type="text"
          value={text}
          onChange={(event) => setText(event.target.value)}
          placeholder="Type something..."
          disabled={isPending}
          className="rounded-md border border-zinc-300 bg-white px-3 py-2 text-sm text-zinc-900 outline-none focus:border-zinc-500 focus:ring-2 focus:ring-zinc-200 disabled:opacity-60 dark:border-zinc-700 dark:bg-zinc-800 dark:text-zinc-100"
        />
        <button
          type="submit"
          disabled={isPending}
          className="inline-flex items-center justify-center rounded-md bg-zinc-900 px-4 py-2 text-sm font-medium text-white transition-colors hover:bg-zinc-700 disabled:cursor-not-allowed disabled:opacity-60 dark:bg-zinc-100 dark:text-zinc-900 dark:hover:bg-zinc-300"
        >
          {isPending ? "Sending..." : "Send"}
        </button>
      </form>

      {state.status === "success" && (
        <div
          role="status"
          className="rounded-md border border-green-300 bg-green-50 px-4 py-3 text-sm text-green-800 dark:border-green-800 dark:bg-green-950 dark:text-green-200"
        >
          <p className="font-semibold">Server response:</p>
          <p className="mt-1">{state.message}</p>
        </div>
      )}

      {state.status === "error" && (
        <div
          role="alert"
          className="rounded-md border border-red-300 bg-red-50 px-4 py-3 text-sm text-red-800 dark:border-red-800 dark:bg-red-950 dark:text-red-200"
        >
          <p className="font-semibold">Error:</p>
          <p className="mt-1">{state.error}</p>
        </div>
      )}
    </div>
  );
}

import { AddMessageForm } from "./_components/AddMessageForm";

export default function Home() {
  return (
    <div className="flex flex-1 flex-col items-center justify-center gap-8 bg-zinc-50 px-6 py-16 font-sans dark:bg-black">
      <div className="flex flex-col items-center gap-2 text-center">
        <h1 className="max-w-md text-3xl font-semibold leading-tight tracking-tight text-black dark:text-zinc-50">
          tRPC v11 + Next.js Server Actions
        </h1>
        <p className="max-w-md text-base leading-7 text-zinc-600 dark:text-zinc-400">
          Submit the form below. The Server Action calls the{" "}
          <code className="rounded bg-zinc-200 px-1.5 py-0.5 text-sm dark:bg-zinc-800">
            addMessage
          </code>{" "}
          mutation via{" "}
          <code className="rounded bg-zinc-200 px-1.5 py-0.5 text-sm dark:bg-zinc-800">
            createCallerFactory
          </code>{" "}
          and returns the result.
        </p>
      </div>

      <AddMessageForm />
    </div>
  );
}

